import {MemoryGame} from './memory-engine.js';
import {loadWords} from './word-store.js';
import {readWords} from './vocab.js';
const $=id=>document.getElementById(id);let game=null,paused=false,last=0,drawnRound=0,finished=false,statusCache='',bestKey='';
function start(){const parsed=readWords(loadWords());try{if(parsed.errors.length)throw Error(parsed.errors[0]);game=new MemoryGame(parsed.entries);}catch(e){$('introError').textContent=e.message;$('intro').classList.remove('hidden');return;}bestKey='treasure-best-v1:'+JSON.stringify(game.pack.map(p=>[p.word,p.meaning]).sort((a,b)=>a[0].localeCompare(b[0])));paused=false;finished=false;drawnRound=0;statusCache='';for(const id of['intro','result','pauseScreen'])$(id).classList.add('hidden');render();}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;$('confetti').replaceChildren();for(let i=0;i<24;i++){const p=document.createElement('i');p.style.setProperty('--x',(i*4.3)+'%');p.style.setProperty('--c',['#ffdc92','#8befc2','#c9afff'][i%3]);p.style.setProperty('--d',i%4*.07+'s');$('confetti').append(p);}setTimeout(()=>$('confetti').replaceChildren(),1700);}
function render(){if(!game)return;const g=game;if(drawnRound!==g.round){drawnRound=g.round;$('board').replaceChildren();for(const c of g.cards){const b=document.createElement('button');b.className='chest';b.type='button';b.innerHTML='<span class="number"></span><span class="kind"></span><span class="lid" aria-hidden="true"></span><span class="label"></span>';b.querySelector('.number').textContent=c.id+1;b.onclick=()=>{if(!paused&&g.flip(c.id)){if(g.lastOutcome==='match'&&g.phase==='resolve')celebrate();render();}};$('board').append(b);}}
 [...$('board').children].forEach((b,i)=>{const c=g.cards[i],open=g.visible(c);b.classList.toggle('open',open);b.classList.toggle('matched',c.matched);b.classList.toggle('miss',g.phase==='resolve'&&g.lastOutcome==='miss'&&g.selected.includes(i));b.classList.toggle('long',c.text.length>15);b.querySelector('.kind').textContent=open?(c.kind==='word'?'ENGLISH':'日本語'):'';b.querySelector('.lid').hidden=open;b.querySelector('.label').textContent=open?c.text:'';b.disabled=paused||g.phase!=='play'||g.hintTime>0||c.matched||g.selected.includes(i);b.setAttribute('aria-label',`${i+1}番の宝箱${open?'：'+c.text:'、閉じています'}${c.matched?'、ペア完成':''}`);});
 $('round').textContent=g.round+' / 3';$('time').textContent=Math.ceil(g.remaining);$('time').classList.toggle('urgent',g.remaining<20);$('timeBar').style.width=g.remaining/90*100+'%';$('score').textContent=g.score.toLocaleString();$('ready').classList.toggle('hidden',g.phase!=='preview');$('hint').classList.toggle('hidden',g.phase==='preview');$('hint').disabled=paused||g.phase!=='play'||g.hintUsed||g.selected.length>0;$('hint').textContent=g.hintUsed?'この部屋のヒントは使用済み':'3秒だけ見る −50点';
 let title,detail;if(g.phase==='preview'){title=`あと${Math.ceil(g.delay)}秒 · 場所をおぼえよう`;detail=`${g.pairs.length}組の英単語と訳。覚えたらすぐ開始できる`;}else if(g.phase==='between'){title='この部屋の宝石を全部ゲット！';detail='次の部屋へ…';}else if(g.hintTime>0){title=`中身を確認 · あと${Math.ceil(g.hintTime)}秒`;detail='閉じたら、もう一度ペアを探そう';}else if(g.phase==='resolve'){title=g.lastOutcome==='match'?`${g.combo}連続ペア！`:'惜しい！ 組み合わせを覚えておこう';detail=g.lastOutcome==='match'?g.lastMatch.word+' ＝ '+g.lastMatch.meaning:'少ししたら、箱が閉じます';}else{title=g.selected.length?'対応するもう一つの箱は？':'英単語と日本語訳をつなごう';detail=`${g.cards.filter(c=>c.matched).length/2} / ${g.pairs.length}組発見 · 連続成功でボーナス`;}
 const status=title+detail;if(status!==statusCache){$('statusTitle').textContent=title;$('statusDetail').textContent=detail;statusCache=status;}
 if(g.phase==='done'&&!finished){finished=true;showResult();}}
function showResult(){const g=game;$('resultKicker').textContent=g.win?'ALL TREASURES FOUND':'TIME UP';$('resultTitle').textContent=g.win?'3部屋の宝石を集めた！':'今回の宝探しはここまで';$('resultScore').textContent=g.score.toLocaleString()+' pts';$('resultStats').textContent=`${g.matches}組発見 ／ ${g.moves}回挑戦\n最大${g.bestCombo}連続 ／ ヒント${g.hints}回`;$('review').replaceChildren();for(const p of g.review.values()){const row=document.createElement('div'),b=document.createElement('b');b.textContent=p.word;row.append(b,document.createTextNode(' — '+p.meaning));$('review').append(row);}$('reviewSection').classList.toggle('hidden',!g.review.size);try{const previous=Number(localStorage.getItem(bestKey))||0;const record=Math.max(previous,g.score);localStorage.setItem(bestKey,String(record));$('best').textContent=`この単語セットの自己ベスト：${record.toLocaleString()}点`;}catch{$('best').textContent='';}$('result').classList.remove('hidden');if(g.win)celebrate();$('again').focus();}
function pause(value){if(!game||game.phase==='done')return;paused=value;$('pauseScreen').classList.toggle('hidden',!value);if(value)$('resume').focus();render();}
$('start').onclick=start;$('again').onclick=start;$('ready').onclick=()=>{if(!paused){game?.begin();render();}};$('hint').onclick=()=>{if(!paused){game?.peek();render();}};$('pause').onclick=()=>pause(true);$('resume').onclick=()=>pause(false);document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);});window.addEventListener('blur',()=>pause(true));window.addEventListener('keydown',e=>{if(e.key==='Escape')pause(!paused);});
function frame(t){const dt=last?Math.min((t-last)/1000,.25):0;last=t;if(game&&!paused&&!document.hidden&&game.phase!=='done'){game.tick(dt);render();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
